3	export function escapeHtml(value: string): string {
4	  return value
5	    .replace(/&/g, '&amp;')
6	    .replace(/</g, '&lt;')
7	    .replace(/>/g, '&gt;')
8	    .replace(/"/g, '&quot;')
9	    .replace(/'/g, '&#39;');
10	}
