12	function layout(title: string, body: string): string {
13	  return `<!DOCTYPE html>
14	<html lang="en">
15	<head>
16	<meta charset="UTF-8">
17	<meta name="viewport" content="width=device-width, initial-scale=1.0">
18	<title>${escapeHtml(title)}</title>
19	</head>
20	<body>
21	${body}
22	</body>
23	</html>
24	`;
25	}
26	
27	export function renderPage(page: Page): string {
28	  const tags = page.tags.length
29	    ? `<ul class="tags">${page.tags.map((tag) => `<li>${escapeHtml(tag)}</li>`).join('')}</ul>`
30	    : '';
31	  const date = page.date ? `<p class="date">${escapeHtml(page.date)}</p>` : '';
32	  const body = `<article>
33	<h1>${escapeHtml(page.title)}</h1>
34	${date}
35	${tags}
36	<div class="content">
37	${page.html}
38	</div>
39	<p><a href="index.html">&larr; Back to index</a></p>
40	</article>`;
41	  return layout(page.title, body);
42	}
