44	export function renderIndex(pages: Page[]): string {
45	  const sorted = [...pages].sort((a, b) => (b.date || '').localeCompare(a.date || ''));
46	  const items = sorted
47	    .map((page) => {
48	      const date = page.date ? ` <span class="date">${escapeHtml(page.date)}</span>` : '';
49	      return `<li><a href="${escapeHtml(page.outputPath)}">${escapeHtml(page.title)}</a>${date}</li>`;
50	    })
51	    .join('\n');
52	  const body = `<h1>Site Index</h1>
53	<ul class="pages">
54	${items}
55	</ul>`;
56	  return layout('Site Index', body);
57	}
