1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { findMarkdownFiles, parseMarkdownFile } from './parser';
4	import { renderIndex, renderPage } from './templates';
5	import { BuildOptions, BuildResult } from './types';
6	
7	export function build(options: BuildOptions): BuildResult {
8	  const contentDir = path.resolve(options.contentDir);
9	  const outputDir = path.resolve(options.outputDir);
10	
11	  if (!fs.existsSync(contentDir)) {
12	    throw new Error(`Content directory not found: ${contentDir}`);
13	  }
14	
15	  const files = findMarkdownFiles(contentDir);
16	  const pages = files.map((file) => parseMarkdownFile(file, contentDir));
17	
18	  const slugCounts = new Map<string, number>();
19	  for (const page of pages) {
20	    slugCounts.set(page.slug, (slugCounts.get(page.slug) || 0) + 1);
21	  }
22	  const duplicates = [...slugCounts.entries()].filter(([, count]) => count > 1);
23	  if (duplicates.length > 0) {
24	    const names = duplicates.map(([slug]) => slug).join(', ');
25	    throw new Error(`Duplicate page slug(s) detected: ${names}`);
26	  }
27	
28	  fs.mkdirSync(outputDir, { recursive: true });
29	
30	  for (const page of pages) {
31	    const outFile = path.join(outputDir, page.outputPath);
32	    fs.mkdirSync(path.dirname(outFile), { recursive: true });
33	    fs.writeFileSync(outFile, renderPage(page), 'utf-8');
34	  }
35	
36	  fs.writeFileSync(path.join(outputDir, 'index.html'), renderIndex(pages), 'utf-8');
37	
38	  return { pages, outputDir };
39	}
