1	import * as fs from 'fs';
2	import * as path from 'path';
3	import matter from 'gray-matter';
4	import { marked } from 'marked';
5	import { Page } from './types';
6	
7	export function slugify(fileName: string): string {
8	  const base = fileName.replace(/\.md$/i, '');
9	  return base
10	    .toLowerCase()
11	    .trim()
12	    .replace(/[^a-z0-9]+/g, '-')
13	    .replace(/^-+|-+$/g, '');
14	}
15	
16	export function titleFromSlug(slug: string): string {
17	  return slug
18	    .split('-')
19	    .filter(Boolean)
20	    .map((word) => word[0].toUpperCase() + word.slice(1))
21	    .join(' ');
22	}
23	
24	export function normalizeDate(date: unknown): string {
25	  if (date instanceof Date) {
26	    return date.toISOString().slice(0, 10);
27	  }
28	  if (typeof date === 'string') {
29	    return date;
30	  }
31	  if (date === undefined || date === null) {
32	    return '';
33	  }
34	  return String(date);
35	}
36	
37	export function normalizeTags(tags: unknown): string[] {
38	  if (Array.isArray(tags)) {
39	    return tags.map((tag) => String(tag).trim()).filter(Boolean);
40	  }
41	  if (typeof tags === 'string') {
42	    return tags
43	      .split(',')
44	      .map((tag) => tag.trim())
45	      .filter(Boolean);
46	  }
47	  return [];
48	}
49	
50	export function parseMarkdownFile(filePath: string, contentDir: string): Page {
51	  const raw = fs.readFileSync(filePath, 'utf-8');
52	  const { data, content } = matter(raw);
53	
54	  const relativePath = path.relative(contentDir, filePath);
55	  const fileName = path.basename(filePath);
56	  const slug = slugify(relativePath.replace(/\\/g, '/'));
57	
58	  const title = typeof data.title === 'string' && data.title.trim() ? data.title.trim() : titleFromSlug(slugify(fileName));
59	  const date = normalizeDate(data.date);
60	  const tags = normalizeTags(data.tags);
61	
62	  const html = marked.parse(content, { async: false }) as string;
63	
64	  return {
65	    title,
66	    date,
67	    tags,
68	    slug,
69	    sourcePath: filePath,
70	    outputPath: `${slug}.html`,
71	    html,
72	  };
73	}
74	
75	export function findMarkdownFiles(dir: string): string[] {
76	  if (!fs.existsSync(dir)) {
77	    return [];
78	  }
79	  const entries = fs.readdirSync(dir, { withFileTypes: true });
80	  const files: string[] = [];
81	  for (const entry of entries) {
82	    const fullPath = path.join(dir, entry.name);
83	    if (entry.isDirectory()) {
84	      files.push(...findMarkdownFiles(fullPath));
85	    } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
86	      files.push(fullPath);
87	    }
88	  }
89	  return files.sort();
90	}
